def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]

    # Recover the colour substitutions written next to the azure objects.
    pairs = []
    for r in range(h):
        for c in range(w - 2):
            a, b, z = grid[r][c:c+3]
            if z == 8 and a not in (0, 8) and b not in (0, 8):
                pairs.append((a, b))
    replacement = {}
    keyed = set()
    for a, b in pairs:
        replacement[a] = b
        replacement[b] = a
        keyed.add(a)
        keyed.add(b)

    # Colours which occur only in a key are not drawing colours.  The drawing
    # colour is the other member of each pair.
    drawing = []
    for a, b in pairs:
        ca = sum(row.count(a) for row in grid)
        cb = sum(row.count(b) for row in grid)
        drawing.append(a if ca >= cb else b)

    for colour in drawing:
        pts = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == colour]
        # Discard key cells next to azure.
        pts = [(r, c) for r, c in pts
               if min((abs(r-er) + abs(c-ec)
                       for er in range(h) for ec in range(w)
                       if grid[er][ec] == 8), default=99) > 2]
        new = replacement[colour]

        # Partition into diagonal runs. Isolated off-pattern specks are noise.
        remaining = set(pts)
        runs = []
        while remaining:
            p = min(remaining)
            remaining.remove(p)
            best = None
            for q in list(remaining):
                dr, dc = q[0]-p[0], q[1]-p[1]
                if dr and abs(dr) == abs(dc):
                    d = max(abs(dr), abs(dc))
                    if best is None or d < best[0]:
                        best = (d, q)
            if best is None:
                continue
            q = best[1]
            run = [p, q]
            remaining.remove(q)
            dr = (q[0]-p[0]) // best[0]
            dc = (q[1]-p[1]) // best[0]
            changed = True
            while changed:
                changed = False
                for x in list(remaining):
                    if (x[0]-run[-1][0], x[1]-run[-1][1]) == (dr, dc):
                        run.append(x)
                        remaining.remove(x)
                        changed = True
            runs.append((run, dr, dc))

        for run, dr, dc in runs:
            # Draw and extrapolate each dashed diagonal stroke.
            r, c = run[0][0]-dr, run[0][1]-dc
            end = (run[-1][0]+dr, run[-1][1]+dc)
            while True:
                if 0 <= r < h and 0 <= c < w:
                    out[r][c] = new
                if (r, c) == end:
                    break
                r += dr
                c += dc
    return out
